// decideDeliveries applies delivery rules 1-7 to today's pending nudges in habit id order.
func decideDeliveries(ctx context.Context, tx *gorm.DB, sender push.PushSender, u db.User,
	p db.NotificationPrefs, now, today time.Time) error {
	var pending []db.Nudge
	if err := tx.Joins("JOIN habits ON habits.id = nudges.habit_id").
		Where("habits.user_id = ? AND habits.deleted_at IS NULL AND habits.archived = ? "+
			"AND nudges.deleted_at IS NULL AND nudges.for_date = ? AND nudges.delivery = ?",
			u.ID, false, today, "pending").
		Order("nudges.habit_id").Find(&pending).Error; err != nil {
		return err
	}
	if len(pending) == 0 {
		return nil
	}
	var devices []db.Device
	if err := tx.Where("user_id = ?", u.ID).Order("id").Find(&devices).Error; err != nil {
		return err
	}
	var sent int64
	if err := tx.Model(&db.Nudge{}).
		Joins("JOIN habits ON habits.id = nudges.habit_id").
		Where("habits.user_id = ? AND nudges.for_date = ? AND nudges.delivery = ?",
			u.ID, today, "sent").Count(&sent).Error; err != nil {
		return err
	}
	quiet := inQuiet(localClock(now, u.Timezone), p.QuietStart, p.QuietEnd)
	for _, n := range pending {
		delivery, reason := "suppressed", ""
		switch {
		case n.DismissedAt != nil:
			reason = "dismissed"
		case n.Kind == "on_track" || n.Kind == "achieved":
			reason = "in_app_only"
		case !p.PushEnabled:
			reason = "push_disabled"
		case len(devices) == 0:
			reason = "no_device"
		case quiet:
			reason = "quiet_hours"
		case sent >= DailyLimit:
			reason = "daily_limit"
		default:
			delivery = "failed"
			for _, dv := range devices {
				if sender.Send(ctx, dv.PushToken, n.Message) == nil {
					delivery = "sent"
				}
			}
			if delivery == "sent" {
				sent++
			}
		}
		seq, err := db.NextChangeSeq(tx, u.ID)
		if err != nil {
			return err
		}
		var r *string
		if reason != "" {
			r = &reason
		}
		if err := tx.Model(&db.Nudge{}).Where("id = ?", n.ID).UpdateColumns(map[string]any{
			"delivery": delivery, "delivery_reason": r, "change_seq": seq,
			"updated_at": now}).Error; err != nil {
			return err
		}
	}
	return nil
}

// Loop runs the pass at start-up and then every minute until ctx ends (R126).
func Loop(ctx context.Context, d Deps, logf func(string, ...any)) {
	tick := time.NewTicker(time.Minute)
	defer tick.Stop()
	for {
		if err := RunDailyPass(ctx, d); err != nil {
			logf("nudger: daily pass: %v", err)
		}
		select {
		case <-ctx.Done():
			return
		case <-tick.C:
		}
	}
}
